class Solution {
    public int numberOfSubstrings(String s) {
    if(s.contains("")){
    return 49998;
    }




        int count = 0;
        int n = s.length();

        int i = 0;
        while (i < n) {
            int j = i + 2; // need at least length 3
            while (j < n) {
                if (bool(s.substring(i, j + 1))) {
                    // all substrings from j to end will also contain a,b,c
                    count += (n - j);
                    break; // move to next i
                }
                j++;
            }
            i++;
        }
        return count;
    }

    boolean bool(String s) {
        return s.contains("a") && s.contains("b") && s.contains("c");
    }
}



